import json
from datetime import datetime
from collections import Counter

# Analyze hourly pattern of deletions to see if there's a pattern
hourly_deletes = Counter()
hourly_reverts = Counter()

with open('/srv/agentbox/runs/20260905T110726Z_claude_claude-haiku-4-5_s1/data/events.jsonl', 'r') as f:
    for line in f:
        try:
            record = json.loads(line)
            time_str = record.get('time', '')
            if time_str:
                dt = datetime.fromisoformat(time_str.replace('Z', '+00:00'))
                hour = dt.hour

                if record.get('event_type') == 'delete':
                    hourly_deletes[hour] += 1
                elif record.get('event_type') == 'revert':
                    hourly_reverts[hour] += 1
        except:
            pass

print("Hourly pattern of deletions (UTC hours):")
for hour in range(24):
    count = hourly_deletes.get(hour, 0)
    if count > 0:
        print(f"  Hour {hour:02d}:00 UTC: {count:4d} deletes")

print("\n\nHourly pattern of reverts (UTC hours):")
for hour in range(24):
    count = hourly_reverts.get(hour, 0)
    if count > 0:
        print(f"  Hour {hour:02d}:00 UTC: {count:4d} reverts")

# Check daily pattern (weekday vs weekend - though we need to calculate days of week)
daily_deletes = Counter()
with open('/srv/agentbox/runs/20260905T110726Z_claude_claude-haiku-4-5_s1/data/events.jsonl', 'r') as f:
    for line in f:
        try:
            record = json.loads(line)
            time_str = record.get('time', '')
            if time_str and record.get('event_type') == 'delete':
                dt = datetime.fromisoformat(time_str.replace('Z', '+00:00'))
                weekday = dt.strftime('%A')
                daily_deletes[weekday] += 1
        except:
            pass

print("\n\nDeleteion activity by day of week:")
day_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
for day in day_order:
    count = daily_deletes.get(day, 0)
    if count > 0:
        print(f"  {day}: {count}")
